#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <ctime>
#include <vector>
#include "dsp/Amp5150.h"
using namespace vamp;
using Clock=std::chrono::steady_clock;
static double cpu(){timespec t{};if(clock_gettime(CLOCK_THREAD_CPUTIME_ID,&t))std::abort();return t.tv_sec*1e6+t.tv_nsec*.001;}
struct Lane {Preamp5150 pre;PowerAmp5150 pa;void prepare(double fs,int ch){pre.setChannelTrims(54.,1.,1.);pre.setTubeSet(TubeSet::make(0));pa.setTubeSet(TubeSet::make(0));pre.setControls(.75,.5,.5,.6,.46);pa.setControls(.5,.5);pre.prepare(fs);pa.prepare(fs);pa.beginSupplySettle();auto settle=[&](double sec){for(int i=0;i<int(fs*sec);++i)processAmp5150(pre,pa,0.,1.);};for(int p=0;p<3;++p){settle(.1);pa.resetSupplyAverage();settle(.1);pa.applySupplyDC();}settle(.15);pa.endSupplySettle();pre.setModeNow(ch);}};
int main(int argc,char**argv){if(argc!=3&&argc!=4)return 2;bool noise=argc==4&&std::atoi(argv[3])!=0;int factor=std::atoi(argv[1]),ch=std::atoi(argv[2]);if((factor!=2&&factor!=4&&factor!=8)||ch<0||ch>2)return 2;constexpr int frames=128,blocks=120,warm=24;constexpr double host=48000,deadline=1e6*frames/host;double fs=host*factor;Lane lanes[2];for(auto& l:lanes){l.prepare(fs,ch);l.pre.setNoise(noise);}std::vector<double> fixture[2];for(int c=0;c<2;++c){fixture[c].resize((blocks+warm)*frames*factor);for(size_t i=0;i<fixture[c].size();++i){double t=i/fs;double env=.2+.8*std::exp(-24.*std::fmod(t,.075));fixture[c][i]=env*(.18*std::sin(6.283185307179586*(c?110.:82.4)*t)+.06*std::sin(6.283185307179586*(c?173.:137.)*t)+.025*std::sin(6.283185307179586*(c?1723.:3731.)*t));}}double overhead=0;for(int i=0;i<10000;++i){double a=cpu();overhead+=cpu()-a;}std::vector<double> ct,wt;ct.reserve(blocks);wt.reserve(blocks);double energy[2]{};for(int b=0;b<blocks+warm;++b){if(b==warm)for(auto& l:lanes){l.pa.statFailures=0;l.pa.statHeld=0;}auto w=Clock::now();double t0=cpu();for(int c=0;c<2;++c){auto& l=lanes[c];for(int i=0;i<frames*factor;++i){double y=processAmp5150(l.pre,l.pa,fixture[c][b*frames*factor+i],1.);if(!std::isfinite(y))return 3;if(b>=warm)energy[c]+=y*y;}}double dt=cpu()-t0;double dw=std::chrono::duration<double,std::micro>(Clock::now()-w).count();if(b>=warm){ct.push_back(dt);wt.push_back(dw);}}if(!(energy[0]>0&&energy[1]>0))return 4;long long failures=0,held=0;for(auto& l:lanes){failures+=l.pa.statFailures;held+=l.pa.statHeld;}int oc=std::count_if(ct.begin(),ct.end(),[&](double x){return x>deadline;}),ow=std::count_if(wt.begin(),wt.end(),[&](double x){return x>deadline;});std::sort(ct.begin(),ct.end());std::sort(wt.begin(),wt.end());double mean=0;for(auto x:ct)mean+=x;printf("factor=%d channel=%d noise=%d deadline_us=%.1f clock_mean_us=%.3f cpu_mean=%.1f cpu_p95=%.1f cpu_p99=%.1f cpu_max=%.1f wall_p99=%.1f wall_max=%.1f cpu_over=%d wall_over=%d energyL=%.9g energyR=%.9g power_fail=%lld power_held=%lld\n",factor,ch,(int)noise,deadline,overhead/10000,mean/blocks,ct[113],ct[118],ct.back(),wt[118],wt.back(),oc,ow,energy[0],energy[1],failures,held);return 0;}
